parameters.jsCode:
// Arma el aviso para la familia según el evento. Escapa todo lo que viene del formulario.
// - tracking_code.notify: código de seguimiento (solicitud recibida o reenvío).
// - enrollment.created: solicitud aprobada → código de matrícula, valores y enlace a Pagos.
// - payment.reminder: recordatorio de la próxima cuota sin pagar (matrícula, por vencer, vencida o mora).
const esc = (s) => String(s ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
const phoneOf = (g) => { const p = String(g.phone ?? "").replace(/\D/g, ""); return !p ? null : p.length === 10 && p.startsWith("0") ? "593" + p.slice(1) : p; };
const wrap = (d, inner) =>
  '<div style="font-family:system-ui,sans-serif;color:#06283B;max-width:560px">' +
  '<h2 style="color:#063F5C">' + esc(d.institution.name) + '</h2>' +
  '<p>Hola ' + esc(d.guardian.name) + ',</p>' + inner +
  '<p style="color:#3D5A6A;font-size:13px">Dudas: ' + esc(d.institution.email) + ' · ' + esc(d.institution.phone) + '</p></div>';

return $input.all().map(({ json }) => {
  const event = json.body.event;
  const d = json.body.data;

  if (event === "enrollment.created") {
    const f = d.fees;
    const inner =
      '<p>¡Felicidades! La solicitud de admisión de <strong>' + esc(d.student.firstName) + '</strong> para ' + esc(d.student.grade) + ' (' + esc(d.academicYear) + ') fue <strong>aprobada</strong>.</p>' +
      '<p>Este es tu código de matrícula:</p>' +
      '<p style="font:600 22px monospace;letter-spacing:1px;background:#E6F6FA;border-radius:8px;padding:10px 14px;display:inline-block">' + esc(d.enrollmentCode) + '</p>' +
      '<ul>' +
      '<li>Matrícula: <strong>' + esc(f.enrollment) + '</strong>, paga hasta el <strong>' + esc(f.enrollmentDue) + '</strong> para completar la inscripción.</li>' +
      '<li>Pensión: ' + esc(f.monthly) + ' × ' + esc(f.months) + ' meses, vence el día ' + esc(f.dueDay) + ' de cada mes.</li>' +
      '</ul>' +
      '<p>Paga a tiempo y suma a tu <strong>récord de puntualidad</strong>: con 80 % o más tu familia gana una beca del 20 % para el año siguiente.</p>' +
      '<p><a href="' + esc(d.paymentsUrl) + '" style="background:#063F5C;color:#fff;padding:10px 16px;border-radius:8px;text-decoration:none;font-weight:600">Ver mis pagos</a></p>' +
      '<p style="font-size:13px">Ingresa con el código de matrícula y la cédula del representante.</p>';
    return { json: {
      to: d.guardian.email,
      phone: phoneOf(d.guardian),
      subject: "Solicitud aprobada · matrícula " + d.enrollmentCode + " · " + d.institution.name,
      html: wrap(d, inner),
      whatsappText: "¡Felicidades! La solicitud de " + d.student.firstName + " fue aprobada. Código de matrícula: " + d.enrollmentCode + ". Matrícula " + d.fees.enrollment + " hasta el " + d.fees.enrollmentDue + ". Ver pagos: " + d.paymentsUrl,
    } };
  }

  if (event === "payment.reminder") {
    // Recordatorio de la PRÓXIMA cuota sin pagar; el tono cambia según el caso y el récord de puntualidad.
    const i = d.installment, r = d.record, s = d.scholarship;
    const pay = '<p><a href="' + esc(d.paymentsUrl) + '" style="background:#063F5C;color:#fff;padding:10px 16px;border-radius:8px;text-decoration:none;font-weight:600">Pagar ahora</a></p>';
    const bar = '<div style="background:#E6F6FA;border-radius:999px;height:12px;width:100%;max-width:420px;position:relative;margin:6px 0">' +
      '<div style="background:#F7AD1A;height:12px;border-radius:999px;width:' + Math.min(100, Number(r.pct) || 0) + '%"></div>' +
      '<div style="position:absolute;left:' + s.minPct + '%;top:-3px;width:2px;height:18px;background:#063F5C"></div></div>' +
      '<p style="font-size:13px;color:#3D5A6A">Tu récord de puntualidad: <strong>' + esc(r.pct) + ' %</strong> · meta para la beca: ' + esc(s.minPct) + ' %</p>';
    const when = i.days > 1 ? 'vence en ' + i.days + ' días, el ' + esc(i.dueDate) : i.days === 1 ? 'vence mañana, ' + esc(i.dueDate) : i.days === 0 ? 'vence hoy, ' + esc(i.dueDate) : 'venció el ' + esc(i.dueDate) + ' (hace ' + (-i.days) + ' días)';
    let subject, inner, wa;
    if (d.kind === "matricula") {
      subject = "Recordatorio: paga la matrícula de " + d.student.firstName;
      inner = '<p>Te recordamos que la <strong>matrícula ' + esc(d.enrollmentCode) + '</strong> de ' + esc(d.student.firstName) + ' (' + esc(d.student.grade) + ') está pendiente de pago.</p>' +
        '<p style="font-size:18px"><strong>' + esc(i.amount) + '</strong> · ' + when + '.</p>' +
        '<p>Al pagarla, la matrícula queda <strong>activa</strong> y el cupo asegurado. Después vienen las pensiones: cada una pagada a tiempo suma a tu récord y con ' + esc(s.minPct) + ' % ganas una <strong>beca del ' + esc(s.discountPct) + ' %</strong> para el año siguiente.</p>' + pay;
      wa = "Recordatorio: la matrícula " + d.enrollmentCode + " de " + d.student.firstName + " (" + i.amount + ") " + when.replace(/<[^>]+>/g, "") + ". Paga aquí: " + d.paymentsUrl;
    } else if (d.kind === "por_vencer") {
      subject = "Tu pensión de " + i.month + " " + (i.days <= 1 ? "vence pronto" : "vence el " + i.dueDate);
      const motiva = r.earned ? '¡Ya alcanzaste la beca! Sigue así.' : r.onTrack ? 'Si pagas a tiempo sumas <strong>+10 %</strong>. Te faltan <strong>' + esc(r.missing) + ' %</strong> para la beca del ' + esc(s.discountPct) + ' %.' : 'Cada pago puntual suma +10 % a tu récord.';
      inner = '<p>La pensión de <strong>' + esc(i.month) + '</strong> de ' + esc(d.student.firstName) + ' (' + esc(i.amount) + ') ' + when + '.</p><p>' + motiva + '</p>' + bar + pay;
      wa = "La pensión de " + i.month + " de " + d.student.firstName + " (" + i.amount + ") " + when.replace(/<[^>]+>/g, "") + ". Pagando a tiempo sumas +10 % para la beca. " + d.paymentsUrl;
    } else if (d.kind === "vencida") {
      subject = "Pensión de " + i.month + " vencida: aún puedes ponerte al día";
      inner = '<p>La pensión de <strong>' + esc(i.month) + '</strong> de ' + esc(d.student.firstName) + ' (' + esc(i.amount) + ') ' + when + '.</p>' +
        '<p>Si la pagas ahora cuenta como atrasada (+5 %) y ' + (r.onTrack || r.pct + 5 >= s.minPct ? '<strong>todavía puedes llegar a la beca</strong>.' : 'mejoras tu récord para el próximo año.') + '</p>' + bar + pay;
      wa = "La pensión de " + i.month + " de " + d.student.firstName + " está vencida (" + i.amount + "). Ponte al día aquí: " + d.paymentsUrl;
    } else {
      subject = "Queremos ayudarte con los pagos de " + d.student.firstName;
      inner = '<p>Notamos que la pensión de <strong>' + esc(i.month) + '</strong> (' + esc(i.amount) + ') ' + when + '.</p>' +
        '<p>Sabemos que pueden surgir imprevistos. <strong>Escríbenos y acordamos un plan de pagos</strong> a tu medida.</p>' + pay;
      wa = "Hola, la pensión de " + i.month + " de " + d.student.firstName + " está pendiente. Escríbenos para acordar un plan de pagos: " + d.institution.email;
    }
    return { json: { to: d.guardian.email, phone: phoneOf(d.guardian), subject: subject + " · " + d.institution.name, html: wrap(d, inner), whatsappText: wa } };
  }

  // tracking_code.notify
  const resend = d.reason === "resend";
  const rows = d.applications.map((a) =>
    '<tr><td style="padding:8px 12px;font:600 18px monospace;letter-spacing:1px">' + esc(a.trackingCode) + '</td>' +
    '<td style="padding:8px 12px">' + esc(a.studentFirstName) + ' · ' + esc(a.grade) + ' · ' + esc(a.academicYear) + '</td>' +
    '<td style="padding:8px 12px">' + esc(a.status) + '</td></tr>').join("");
  const statusUrl = d.statusUrl; // la app manda el enlace completo (n8n Cloud no expone variables de entorno)
  const inner =
    '<p>' + (resend ? 'Recibimos un pedido para recordar tus códigos de seguimiento.' : 'Recibimos tu solicitud de admisión. Este es tu código de seguimiento:') + '</p>' +
    '<table style="border-collapse:collapse;background:#E6F6FA;border-radius:8px">' + rows + '</table>' +
    '<p>Para consultar el estado ingresa a <a href="' + esc(statusUrl) + '">' + esc(statusUrl) + '</a> con el código y la cédula del representante.</p>' +
    (resend ? '<p style="color:#3D5A6A;font-size:13px">Si no pediste este correo, puedes ignorarlo: nadie puede ver tu solicitud sin tu cédula.</p>' : '');
  const codes = d.applications.map((a) => a.trackingCode).join(", ");
  return { json: {
    to: d.guardian.email,
    // WhatsApp Cloud API: solo dígitos con código de país (Ecuador: 09XXXXXXXX → 5939XXXXXXXX).
    phone: phoneOf(d.guardian),
    subject: (resend ? "Tus códigos de seguimiento · " : "Solicitud recibida · ") + d.institution.name,
    html: wrap(d, inner),
    whatsappText: (resend ? "Tus códigos de seguimiento: " : "Recibimos tu solicitud. Tu código de seguimiento es ") + codes + ". Consulta el estado en " + statusUrl,
  } };
});
